import com.sap.it.api.mapping.*;// Extracts the segment after the last underscore (_) from the given string.// For example, input: "GUY_9G_NORMHRS" -> output: "NORMHRS"def String customFunc(String workScheduleRule){    if (workScheduleRule == null || workScheduleRule.trim() == "") {        return ""    }    // Split the string by underscore and return the last segment    return workScheduleRule.tokenize('_').last()}